import json
s=json.load(open('results/summary_main.json'))
print(s['n_runs'], s['n_joint_runs'], s['run_minutes_mean'])
import pandas as pd
print(pd.DataFrame(s['baselines']).T.round(3))
for k in ['H1_shape_loss','H1_shape_rel_metric']:
    h=s[k]
