        if isinstance(v,dict) and 'best' in v:
            print(k,n,v['n_traj'],v['best'],{a:round(b-min(v['aicc'].values()),1) for a,b in v['aicc'].items()}, {a:round(b,3) for a,b in v['r2'].items()}, v['params']['power'])
        else: print(k,n,v)
for c,v in s['H2_domain']['ratios'].items(): print(c,{a:(round(b,3) if isinstance(b,float) else b) for a,b in v.items()})
print(pd.DataFrame(s['H2_domain']['per_task']).T.round(3).to_string())
for c,v in s['H3_position'].items(): print(c,json.dumps(v)[:900])
print(s['interference']); print(pd.DataFrame(s['format_vs_content']).T.round(3))
E
